        return new long[0];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken(); int a = (int) in.nval;
        in.nextToken(); int b = (int) in.nval;
        long[][] day1 = new long[a][3], day2 = new long[b][3];
        for (int i = 0; i < a; i++)
            for (int j = 0; j < 3; j++) { in.nextToken(); day1[i][j] = (long) in.nval; }
        for (int i = 0; i < b; i++)
            for (int j = 0; j < 3; j++) { in.nextToken(); day2[i][j] = (long) in.nval; }
        long[] res = loyalCustomers(day1, day2);
        if (res.length == 0) { System.out.println(-1); return; }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "\n");
        System.out.print(sb);
    }
}
